"""Retail Intelligence: sales analytics and AI-assisted customer segmentation.

Author field: Anamika Negi. AI-assisted educational project; review before submission.
Run dashboard: streamlit run AnamikaNegi_RetailIntelligence.py
Run reproducible analysis: python AnamikaNegi_RetailIntelligence.py --analyze
Dataset: https://archive.ics.uci.edu/dataset/352/online+retail
"""

from __future__ import annotations

import argparse
import os
os.environ.setdefault("OMP_NUM_THREADS", "2")
os.environ.setdefault("OPENBLAS_NUM_THREADS", "2")
import hashlib
import io
import json
from pathlib import Path
import urllib.request
import zipfile

import numpy as np
import pandas as pd
from sklearn.cluster import KMeans
from sklearn.metrics import silhouette_score
from sklearn.preprocessing import StandardScaler

DATASET_URL = "https://archive.ics.uci.edu/static/public/352/online+retail.zip"
START = pd.Timestamp("2010-12-01")
STOP = pd.Timestamp("2011-12-01")  # Exclusive: excludes incomplete December 2011.
SEED = 42
BASE = Path(__file__).resolve().parent
# Canonical, verified chart snapshots are inserted here by the project build.
import base64
import zlib
_CHART_ARCHIVE = {'monthly': '', 'countries': '', 'segments': ''}
CHARTS = {key: zlib.decompress(base64.b64decode(value)).decode("utf-8") for key, value in _CHART_ARCHIVE.items()}
CHART_FINGERPRINT = 'ca0b07382493f68a23542fd9d72df0063b2964cdb09aa8acc7170e48a18fccd5'


def download_data(path: Path) -> Path:
    """Download the public source once; no authentication or private data used."""
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        request = urllib.request.Request(DATASET_URL, headers={"User-Agent": "RetailIntelligence/1.0"})
        with urllib.request.urlopen(request, timeout=120) as response:
            archive = zipfile.ZipFile(io.BytesIO(response.read()))
        name = next(n for n in archive.namelist() if n.lower().endswith(".xlsx"))
        temporary = path.with_suffix(".tmp")
        temporary.write_bytes(archive.read(name))
        temporary.replace(path)
    return path


def analyze(path: Path) -> dict:
    """Clean source transactions, compute reconciled KPIs, and segment customers."""
    raw = pd.read_excel(path, engine="openpyxl")
    required = {"InvoiceNo", "StockCode", "Description", "Quantity", "InvoiceDate",
                "UnitPrice", "CustomerID", "Country"}
    if not required.issubset(raw.columns):
        raise ValueError(f"Missing required columns: {sorted(required - set(raw.columns))}")

    steps = [{"step": "Raw source rows", "rows": len(raw), "removed": 0}]
    data = raw.drop_duplicates().copy()
    steps.append({"step": "Remove exact duplicate rows", "rows": len(data),
                  "removed": len(raw) - len(data)})
    data["InvoiceNo"] = data["InvoiceNo"].astype(str).str.strip()
    data["StockCode"] = data["StockCode"].astype(str).str.strip()
    data["InvoiceDate"] = pd.to_datetime(data["InvoiceDate"], errors="coerce")
    for col in ["Quantity", "UnitPrice", "CustomerID"]:
        data[col] = pd.to_numeric(data[col], errors="coerce")

    def retain(mask: pd.Series, description: str) -> None:
        nonlocal data
        before = len(data)
        data = data.loc[mask].copy()
        steps.append({"step": description, "rows": len(data), "removed": before - len(data)})

    retain(data["InvoiceDate"].ge(START) & data["InvoiceDate"].lt(STOP),
           "Keep December 2010–November 2011 (complete-month window)")
    # These are return/cancellation lines, not a net-sales or profit measure.
    cancelled = data.loc[data["InvoiceNo"].str.upper().str.startswith("C") |
                         data["Quantity"].lt(0)].copy()
    cancelled_amount = float((cancelled["Quantity"].abs() *
                              cancelled["UnitPrice"].clip(lower=0)).sum())
    retain(~data["InvoiceNo"].str.upper().str.startswith("C") & data["Quantity"].gt(0),
           "Exclude cancellations, returns and non-positive quantities")
    retain(data["UnitPrice"].gt(0) & np.isfinite(data["UnitPrice"]),
           "Exclude missing, free and non-positive unit prices")
    # UCI has postage, bank charges and manual adjustments with non-product codes.
    retain(data["StockCode"].str.fullmatch(r"\d{5}[A-Za-z]?").fillna(False),
           "Keep product codes; exclude postage/manual/non-product codes")
    data["Description"] = data["Description"].fillna("Description unavailable")
    data["Country"] = data["Country"].fillna("Unknown")
    data["SalesGBP"] = data["Quantity"] * data["UnitPrice"]
    if data.empty or not np.isfinite(data["SalesGBP"]).all():
        raise ValueError("No valid sales remain, or non-finite sales detected.")

    known = data.loc[data["CustomerID"].notna()].copy()
    known["CustomerID"] = known["CustomerID"].astype("int64").astype(str)
    order_values = data.groupby("InvoiceNo")["SalesGBP"].sum()
    monthly = data.groupby(data["InvoiceDate"].dt.to_period("M")).agg(
        SalesGBP=("SalesGBP", "sum"), Orders=("InvoiceNo", "nunique"),
        Units=("Quantity", "sum"))
    monthly = monthly.reindex(pd.period_range(START, STOP - pd.Timedelta(days=1), freq="M"))
    monthly.index.name = "Month"
    if monthly.isna().any().any():
        raise ValueError("A reporting month has no observations; do not treat it as zero.")
    monthly["SalesChangePct"] = monthly["SalesGBP"].pct_change() * 100
    monthly["AverageOrderValueGBP"] = monthly["SalesGBP"] / monthly["Orders"]
    countries = data.groupby("Country").agg(
        SalesGBP=("SalesGBP", "sum"), Orders=("InvoiceNo", "nunique"),
        IdentifiedCustomers=("CustomerID", "nunique")).sort_values("SalesGBP", ascending=False)
    products = data.groupby("StockCode").agg(
        Description=("Description", lambda x: x.mode().iloc[0] if len(x.mode()) else x.iloc[0]),
        SalesGBP=("SalesGBP", "sum"), Units=("Quantity", "sum"),
        Orders=("InvoiceNo", "nunique")).sort_values("SalesGBP", ascending=False)

    rfm = known.groupby("CustomerID").agg(
        LastPurchase=("InvoiceDate", "max"),
        Frequency=("InvoiceNo", "nunique"), MonetaryGBP=("SalesGBP", "sum"))
    rfm["RecencyDays"] = (STOP - rfm["LastPurchase"].dt.normalize()).dt.days
    transformed = np.log1p(rfm[["RecencyDays", "Frequency", "MonetaryGBP"]])
    scaled = StandardScaler().fit_transform(transformed)
    model = KMeans(n_clusters=4, random_state=SEED, n_init=20)
    raw_labels = model.fit_predict(scaled)
    rfm["RawCluster"] = raw_labels
    # Stable display ordering: Segment 1 has the highest median historical spend.
    order = rfm.groupby("RawCluster")["MonetaryGBP"].median().sort_values(ascending=False).index
    names = {int(c): f"Segment {i + 1}" for i, c in enumerate(order)}
    rfm["Segment"] = rfm["RawCluster"].map(names)
    segments = rfm.groupby("Segment").agg(
        Customers=("MonetaryGBP", "size"), SalesGBP=("MonetaryGBP", "sum"),
        MedianRecencyDays=("RecencyDays", "median"),
        MedianOrders=("Frequency", "median"), MedianSpendGBP=("MonetaryGBP", "median"))
    segments["CustomerSharePct"] = segments["Customers"] / len(rfm) * 100
    segments["SalesSharePct"] = segments["SalesGBP"] / rfm["MonetaryGBP"].sum() * 100
    silhouette = float(silhouette_score(scaled, raw_labels, sample_size=min(1000, len(rfm)),
                                       random_state=SEED))
    spend_cutoff = float(rfm["MonetaryGBP"].quantile(0.75))
    rfm["RetentionReview"] = rfm["RecencyDays"].gt(90) & rfm["MonetaryGBP"].ge(spend_cutoff)
    risk = rfm.loc[rfm["RetentionReview"]].sort_values("MonetaryGBP", ascending=False)
    kpis = {
        "raw_rows": len(raw), "sales_rows": len(data),
        "sales_gbp": float(data["SalesGBP"].sum()),
        "orders": int(data["InvoiceNo"].nunique()),
        "identified_customers": len(rfm),
        "average_order_value_gbp": float(order_values.mean()),
        "identified_sales_gbp": float(known["SalesGBP"].sum()),
        "anonymous_sales_gbp": float(data.loc[data["CustomerID"].isna(), "SalesGBP"].sum()),
        "cancelled_or_returned_amount_gbp": cancelled_amount,
        "retention_review_customers": len(risk),
        "retention_review_historical_sales_gbp": float(risk["MonetaryGBP"].sum()),
        "retention_spend_cutoff_gbp": spend_cutoff,
        "silhouette_sample_score": silhouette,
        "first_last_month_change_pct": float(
            (monthly["SalesGBP"].iloc[-1] / monthly["SalesGBP"].iloc[0] - 1) * 100),
        "peak_month": str(monthly["SalesGBP"].idxmax()),
    }
    # Independent revenue check from retained raw quantities/prices, not SalesGBP.
    independent_revenue = float(np.dot(data["Quantity"].to_numpy(),
                                       data["UnitPrice"].to_numpy()))
    assert np.isclose(kpis["sales_gbp"], independent_revenue)
    assert np.isclose(monthly["SalesGBP"].sum(), kpis["sales_gbp"])
    assert np.isclose(countries["SalesGBP"].sum(), kpis["sales_gbp"])
    assert np.isclose(products["SalesGBP"].sum(), kpis["sales_gbp"])
    assert np.isclose(segments["SalesGBP"].sum(), kpis["identified_sales_gbp"])
    assert segments["Customers"].sum() == len(rfm)
    assert sum(s["removed"] for s in steps) + len(data) == len(raw)
    kpis["independent_revenue_check_gbp"] = independent_revenue
    coverage = float(kpis["identified_sales_gbp"] / kpis["sales_gbp"] * 100)
    kpis["identified_sales_coverage_pct"] = coverage

    facts = [
        {"Fact": f"Highest monthly product sales: {kpis['peak_month']}.",
         "Interpretation": "Recorded demand is seasonal; this is association, not proof of a cause.",
         "Recommended action": "Test inventory and staffing plans ahead of the late-year selling period.",
         "Validation": "Track stockouts, fulfilment time and incremental sales in the next comparable period."},
        {"Fact": f"{countries.index[0]} leads product sales in this dataset.",
         "Interpretation": "A concentrated geographic sales base creates dependence on one market.",
         "Recommended action": "Investigate demand and logistics in existing smaller markets before expanding.",
         "Validation": "Measure contribution margin and delivery cost; neither is available in this source."},
        {"Fact": f"{len(risk)} high-spend customers have not purchased for more than 90 days.",
         "Interpretation": "This is a retention-review heuristic, NOT confirmed churn or future lost revenue.",
         "Recommended action": "Run a small, consent-aware reactivation test with a randomized holdout.",
         "Validation": "Compare 30-day repeat-purchase rate and net contribution against the holdout."},
        {"Fact": "K-means creates four behavioral segments from log-transformed RFM features.",
         "Interpretation": "Segments describe historical behavior; no future customer outcome is predicted.",
         "Recommended action": "Tailor onboarding, loyalty and reactivation experiments by segment.",
         "Validation": "Review cluster stability, sample sizes and incremental campaign results."},
    ]
    return {"kpis": kpis, "cleaning": pd.DataFrame(steps), "monthly": monthly,
            "countries": countries, "products": products, "rfm": rfm,
            "segments": segments, "actions": pd.DataFrame(facts)}


def fingerprint(result: dict) -> str:
    # Chart data are fixed to the documented public source/window.
    payload = {"monthly": result["monthly"]["SalesGBP"].round(6).tolist(),
               "countries": result["countries"]["SalesGBP"].round(6).tolist(),
               "segments": result["segments"].round(6).to_json(),
               "kpis": result["kpis"]}
    return hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()


def export_results(result: dict, output: Path) -> None:
    output.mkdir(parents=True, exist_ok=True)
    for key in ["cleaning", "monthly", "countries", "products", "rfm", "segments", "actions"]:
        result[key].to_csv(output / f"{key}.csv", index=key not in {"cleaning", "actions"})
    (output / "metrics.json").write_text(json.dumps(result["kpis"], indent=2), encoding="utf-8")
    (output / "validation.json").write_text(json.dumps({
        "revenue_cross_checks": "passed", "row_accounting": "passed",
        "customer_count_reconciliation": "passed", "chart_fingerprint": fingerprint(result),
        "window": ["2010-12-01", "2011-11-30"],
        "chart_plan": [
            {"comparison": "Monthly product sales", "grain": "calendar month",
             "population": "eligible product sales", "unit": "GBP", "disposition": "chart"},
            {"comparison": "Geographic sales concentration", "grain": "country",
             "population": "eligible product sales", "unit": "GBP", "disposition": "chart"},
            {"comparison": "Customer mix versus sales mix", "grain": "customer segment",
             "population": "identified customers only", "unit": "percent",
             "disposition": "chart"},
            {"comparison": "Products, model diagnostics and retention candidates",
             "grain": "product/customer", "disposition": "table",
             "reason": "Detailed lookup; source lacks costs, actual churn and intervention outcomes."}]
    }, indent=2), encoding="utf-8")


def dashboard() -> None:
    import streamlit as st
    import streamlit.components.v1 as components
    st.set_page_config(page_title="Retail Intelligence", page_icon="🛍️", layout="wide")
    st.title("Retail Intelligence")
    st.caption("Sales analytics • AI-assisted customer segmentation • decision-ready recommendations")
    st.info("Historical educational analysis: December 2010–November 2011 • Currency: GBP. "
            "Product sales exclude refunds and non-product charges; they are NOT net revenue or profit.")

    @st.cache_data(show_spinner=False)
    def cached_analysis(path_string: str, file_size: int) -> dict:
        return analyze(Path(path_string))

    try:
        with st.spinner("Loading public UCI data and calculating the dashboard..."):
            path = download_data(BASE / ".cache" / "Online Retail.xlsx")
            result = cached_analysis(str(path), path.stat().st_size)
    except Exception as exc:
        st.error(f"Dataset could not be loaded: {exc}")
        st.write("Check the internet connection. Alternatively download the source workbook "
                 "and save it as .cache/Online Retail.xlsx beside this code file, then rerun.")
        st.stop()
    verified_charts = bool(CHARTS) and fingerprint(result) == CHART_FINGERPRINT

    def chart(key: str, height: int = 500) -> None:
        if verified_charts:
            components.html(CHARTS[key], height=height, scrolling=True)
        else:
            st.warning("Chart snapshots do not match this data/library environment. "
                       "Use the freshly recomputed tables below; no stale chart will be shown.")

    k = result["kpis"]
    a, b, c, d = st.columns(4)
    a.metric("Product sales (GBP)", f"£{k['sales_gbp']:,.0f}")
    b.metric("Orders", f"{k['orders']:,}")
    c.metric("Identified customers", f"{k['identified_customers']:,}")
    d.metric("Average order value", f"£{k['average_order_value_gbp']:,.2f}")
    view = st.radio("Choose analysis view", ["Executive overview", "Sales & products",
                    "Customers & retention", "Data quality & methodology"], horizontal=True)
    if view == "Executive overview":
        chart("monthly", 470)
        st.subheader("From facts to action")
        st.dataframe(result["actions"], hide_index=True, width="stretch")
        st.caption("Suggested actions are hypotheses for testing, not demonstrated business results.")
    elif view == "Sales & products":
        chart("countries", 500)
        st.subheader("Monthly results — all reporting months")
        st.dataframe(result["monthly"].reset_index().assign(
            Month=lambda x: x["Month"].astype(str)), hide_index=True, width="stretch")
        st.subheader("Product lookup")
        query = st.text_input("Search product description or stock code")
        products = result["products"].reset_index()
        if query:
            products = products.loc[
                products["Description"].str.contains(query, case=False, regex=False) |
                products["StockCode"].astype(str).str.contains(query, case=False, regex=False)]
        st.dataframe(products, hide_index=True, width="stretch")
        st.download_button("Download full product analysis",
                           result["products"].to_csv().encode(), "products.csv", "text/csv")
        st.subheader("All countries")
        st.dataframe(result["countries"], width="stretch")
    elif view == "Customers & retention":
        st.caption(f"Customer analysis covers {k['identified_sales_coverage_pct']:.1f}% of product sales. "
                   "Rows with missing CustomerID remain in sales KPIs but cannot be segmented.")
        chart("segments", 475)
        st.subheader("Behavioral segment profiles")
        st.dataframe(result["segments"], width="stretch")
        st.write(f"Silhouette score (deterministic sample of up to 1,000 customers): "
                 f"{k['silhouette_sample_score']:.3f}. Four clusters are an exploratory "
                 "design choice, not a demonstrated optimal number of segments.")
        st.subheader("Retention review — not a churn prediction")
        st.write(f"{k['retention_review_customers']} customers meet the rule: no purchase "
                 "for >90 days and historical spend at or above the 75th percentile "
                 f"(£{k['retention_spend_cutoff_gbp']:,.2f}). Historical spend is NOT future revenue at risk.")
        candidates = result["rfm"].loc[result["rfm"]["RetentionReview"]].sort_values(
            "MonetaryGBP", ascending=False)
        st.dataframe(candidates.drop(columns=["RawCluster"]), width="stretch")
    else:
        st.subheader("Sequential cleaning audit")
        st.dataframe(result["cleaning"], hide_index=True, width="stretch")
        st.markdown(
            "### Definitions and safeguards\n"
            "- Source: [UCI Online Retail](https://archive.ics.uci.edu/dataset/352/online+retail).\n"
            "- One raw row is an invoice line; one order is a distinct eligible InvoiceNo.\n"
            "- Product sales = Quantity × UnitPrice in GBP; costs and profit are unavailable.\n"
            "- December 2011 is excluded because the source ends partway through that month.\n"
            "- Exact duplicates are removed. Positive but unusually large transactions are retained.\n"
            "- Recency is measured at 1 December 2011, not today.\n"
            "- K-means uses standardized log1p(recency, frequency, monetary), seed 42, "
            "four clusters and 20 initializations; no train/test accuracy is claimed.\n"
            "- The >90-day retention rule is an explicit assumption, not a labeled churn outcome.\n"
            "- No causal attribution, sales forecast or real-world campaign uplift is claimed.\n"
            "- AI assisted development and documentation; all numerical results are computed in Python."
        )
        st.success("Revenue, row-accounting and customer-segment reconciliation checks passed.")
    st.divider()
    st.caption("Anamika Negi • AICTE | IBM SkillsBuild Data Analytics with AI Internship 2026 | "
               "BharatCares • Educational project, not an official IBM product")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--analyze", action="store_true", help="Export analysis without starting the UI")
    parser.add_argument("--data", type=Path, help="Optional local UCI Online Retail workbook path")
    parser.add_argument("--output", type=Path, default=BASE / "outputs")
    args = parser.parse_args()
    if args.analyze:
        source = args.data or download_data(BASE / ".cache" / "Online Retail.xlsx")
        results = analyze(source)
        export_results(results, args.output)
        print(json.dumps(results["kpis"], indent=2))
    else:
        dashboard()
